/*
 * A398367  Values written by the walker in the trampled carousel process.
 * https://oeis.org/A398367
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy, changed
 * Formula:   not stated
 * Range:     u8 n <= 87, u16 n <= 87, u32 n <= 87, u64 n <= 87, u128 n <= 87,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Implementation of OEIS sequence A398367
 * (trampled carousel process).
 * a(1)=1; a(n) is generated by
 *   - insert a new zero-valued cell at the end of the circle;
 *   - increment the cell currently occupied by the walker;
 *   - record its new value as a(n);
 *   - move the walker a(n) cells counter‑clockwise
 *     (i.e. subtract a(n) modulo the current number of cells).
 * This implementation uses lazy incremental computation with
 * static cached state.  It is valid C11 and C++17; for arbitrary
 * precision seq_t the malloc/realloc/calloc results are cast to
 * seq_t* with C‑style casts, which are acceptable in both languages.
 */

#include <stdlib.h>   /* calloc, realloc, abort */

/* Ensure capacity of a dynamic array of seq_t. */
static void ensure_seq_capacity(size_t *cap, seq_t **arr, size_t needed)
{
    if (*cap <= needed) {
        size_t newcap = (*cap == 0) ? 1 : *cap;
        while (newcap <= needed) newcap <<= 1;
        seq_t *tmp = (seq_t*)realloc(*arr, newcap * sizeof(seq_t));
        if (!tmp) abort();
        *arr = tmp;
        *cap = newcap;
    }
}

/* Sequence calculation function. */
seq_t a(idx_t n)
{
    static size_t  computed   = 0;   /* highest n computed so far */
    static size_t  cache_cap  = 0;   /* capacity of a_cache array   */
    static size_t  cells_cap  = 0;   /* capacity of cells array     */
    static seq_t *a_cache    = NULL; /* a_cache[1..computed] holds a(1..computed) */
    static seq_t *cells      = NULL; /* current cell values          */
    static idx_t   walker    = 0;    /* current walker position      */
    static size_t  cells_count = 1;  /* current number of cells      */

    if (n == 0) return 0;            /* undefined for n==0, return 0 */

    /* Lazy initialization on first call. */
    if (!a_cache) {
        // Allocate initial capacity for cache and cells.
        cache_cap = 2;
        cells_cap = 2;
        a_cache = (seq_t*)calloc(cache_cap, sizeof(seq_t));
        if (!a_cache) abort();
        cells   = (seq_t*)calloc(cells_cap, sizeof(seq_t));
        if (!cells) abort();

        /* unused entry at index 0 */
        a_cache[0] = 0;
        cells[0]   = 0;                /* initial cell value = 0 */
        walker      = 0;
        cells_count = 1;
    }

    /* Return cached value if already computed. */
    if (n <= (idx_t)computed) return a_cache[n];

    /* Compute values up to n incrementally. */
    for (idx_t step = (idx_t)computed + 1; step <= n; ++step) {
        /* Step 1: append new cell with value 0. */
        ensure_seq_capacity(&cells_cap, &cells, cells_count + 1);
        cells[cells_count] = 0;
        ++cells_count;                             /* new number of cells */

        /* Step 2: increment current cell and record its value. */
        seq_t an = ++cells[walker];

        /* Store in cache. */
        ensure_seq_capacity(&cache_cap, &a_cache, (size_t)step);
        a_cache[step] = an;

        /* Step 3: move walker a(n) cells counter‑clockwise. */
        seq_t mod_cells = (seq_t)cells_count;
        seq_t an_mod_seq = an % mod_cells;         /* 0 <= an_mod_seq < cells_count */
        idx_t an_mod = (idx_t)an_mod_seq;          /* safe: value < cells_count */

        if (walker >= an_mod) {
            walker -= an_mod;
        } else {
            walker = walker + cells_count - an_mod;
        }
    }

    computed = (size_t)n;
    return a_cache[n];
}
